class Solution { public:int minimumCoins(vector<int>& prices){int n=prices.size();vector<int> dp(n+1);deque<int> candidates={n};for(int i=n-1;i>=0;--i){int right=min(n,2*i+2);while(candidates.front()>right)candidates.pop_front();dp[i]=prices[i]+dp[candidates.front()];while(!candidates.empty()&&dp[candidates.back()]>=dp[i])candidates.pop_back();candidates.push_back(i);}return dp[0];} };
